<section class="single-herbs-guide__section" aria-labelledby="topic-five-foundations"><h4 id="topic-five-foundations"><?php echo s($damptext('Herbs that Clear Heat and Dry Dampness: general introduction', 'Hierbas que aclaran Calor y secan Humedad: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($damptext('These bitter-cold herbs treat the heavy, sticky combination of Heat and Dampness. The Board shortcut is location: upper, middle, lower or the Liver channel connecting both ends.', 'Estas hierbas amargas y frías tratan la combinación pesada y pegajosa de Calor y Humedad. El atajo Board es la localización: superior, media, inferior o el canal de Hígado conectando ambos extremos.')); ?></p><div class="single-herbs-guide__pattern"><article><strong><?php echo s($damptext('Typical presentation', 'Presentación típica')); ?></strong><span><?php echo s($damptext('Heaviness, fullness, sticky yellow discharge, foul odor, itching, jaundice, dysuria or diarrhea with a greasy yellow coat and slippery-rapid pulse.', 'Pesadez, plenitud, secreción amarilla pegajosa, olor fétido, prurito, ictericia, disuria o diarrea con capa amarilla grasosa y pulso resbaladizo-rápido.')); ?></span></article><article><strong><?php echo s($damptext('San Huang map', 'Mapa de San Huang')); ?></strong><span><?php echo s($damptext('Huang Qin = upper. Huang Lian = middle. Huang Bai = lower.', 'Huang Qin = superior. Huang Lian = medio. Huang Bai = inferior.')); ?></span></article><article><strong><?php echo s($damptext('Liver bridge', 'Puente de Hígado')); ?></strong><span><?php echo s($damptext('Long Dan Cao links Liver Fire above with Liver-channel Damp-Heat below.', 'Long Dan Cao conecta Fuego de Hígado arriba con Humedad-Calor del canal de Hígado abajo.')); ?></span></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($damptext('General precautions:', 'Precauciones generales:')); ?></strong> <?php echo s($damptext('bitterness dries Dampness but can also injure fluids; cold clears Heat but can damage Spleen/Stomach Yang. Avoid indiscriminate long or high-dose use, especially in deficiency-Cold.', 'lo amargo seca Humedad, pero también puede lesionar líquidos; lo frío aclara Calor, pero puede dañar Yang de Bazo/Estómago. Evita uso indiscriminado, prolongado o alto, especialmente en deficiencia-Frío.')); ?></p><aside class="single-herbs-guide__memory-path" aria-label="<?php echo s($damptext('Yellow guards memory path', 'Recorrido mnemotécnico de los guardianes amarillos')); ?>"><p class="single-herbs-guide__memory-line"><?php echo s($damptext('The overheated house has flooded with sticky yellow water. Four guards divide the cleanup.', 'La casa recalentada se inundó con agua amarilla pegajosa. Cuatro guardianes dividen la limpieza.')); ?></p><p><?php echo s($damptext('Huang Qin dries the upper floor; Huang Lian cleans the kitchen and Heart control room; Huang Bai drains the basement; Long Dan Cao runs a gutter from the Liver roof to the lower exit.', 'Huang Qin seca el piso superior; Huang Lian limpia la cocina y el control de Corazón; Huang Bai drena el sótano; Long Dan Cao crea una canaleta desde el techo de Hígado hasta la salida inferior.')); ?></p><p><strong><?php echo s($damptext('Three yellow floors plus one Liver channel.', 'Tres pisos amarillos más un canal de Hígado.')); ?></strong></p></aside><h5 class="single-herbs-guide__catalog-heading"><?php echo s($damptext('Current Board category herbs', 'Hierbas de la categoría Board vigente')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($damptext('Study these four herbs named in the module first. The annex remains separate.', 'Estudia primero estas cuatro hierbas nombradas en el módulo. El anexo permanece separado.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($dampherbs as $categoryherb): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($damptext('In Board category list', 'En el listado de la categoría Board')); ?></span></div><p><?php echo s($categoryherb['identity']); ?></p></li><?php endforeach; ?></ol><div class="single-herbs-guide__annex"><h5 class="single-herbs-guide__catalog-heading"><?php echo s($damptext('Annex · Additional official recognition herbs', 'Anexo · Hierbas oficiales adicionales para reconocimiento')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($damptext('All three remain in official Appendix A but are not mixed into this module’s four-herb sequence.', 'Las tres permanecen en el Apéndice A oficial, pero no se mezclan con la secuencia de cuatro hierbas de este módulo.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($dampannex as $categoryherb): ?><li class="single-herbs-guide__category-herb"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge single-herbs-guide__category-herb-badge--outside"><?php echo s($damptext('Official annex recognition', 'Reconocimiento oficial de anexo')); ?></span></div><p><?php echo s($categoryherb['note']); ?></p></li><?php endforeach; ?></ol></div></section>

