rol single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($damptext('Show answer', 'Mostrar respuesta')); ?>" data-hide-label="<?php echo s($damptext('Show question', 'Mostrar pregunta')); ?>"><?php echo s($damptext('Show answer', 'Mostrar respuesta')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($damptext('Next', 'Siguiente')); ?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($damptext('Card', 'Tarjeta')); ?> 1 <?php echo s($damptext('of', 'de')); ?> <?php echo count($dampquestions); ?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-five-recall-title"><h4 id="topic-five-recall-title"><?php echo s($damptext('Quick recall', 'Repaso rápido')); ?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($damptext('Which yellow herb belongs upstairs?', '¿Qué hierba amarilla pertenece al piso superior?')); ?></summary><p><strong>Huang Qin.</strong> <?php echo s($damptext('Think Lung/Upper Jiao, then add bleeding and fetus.', 'Piensa Pulmón/Jiao Superior y luego añade sangrado y feto.')); ?></p></details><details><summary><?php echo s($damptext('Which yellow herb controls the Heart and Stomach center?', '¿Qué hierba amarilla controla el centro Corazón-Estómago?')); ?></summary><p><strong>Huang Lian.</strong> <?php echo s($damptext('It is the central and strongest Middle-Jiao bitter-cold member.', 'Es la integrante amarga-fría central y más potente para el Jiao Medio.')); ?></p></details><details><summary><?php echo s($damptext('Which yellow herb drains the basement?', '¿Qué hierba amarilla drena el sótano?')); ?></summary><p><strong>Huang Bai.</strong> <?php echo s($damptext('Think Kidney, Bladder, legs and deficiency Fire.', 'Piensa Riñón, Vejiga, piernas y Fuego por deficiencia.')); ?></p></details><details><summary><?php echo s($damptext('Which herb links red eyes above with genital Damp-Heat below?', '¿Qué hierba conecta ojos rojos arriba con Humedad-Calor genital abajo?')); ?></summary><p><strong>Long Dan Cao.</strong> <?php echo s($damptext('That two-level Liver-channel pattern is decisive.', 'Ese patrón de dos niveles del canal de Hígado es decisivo.')); ?></p></details></div></section>

